"const fs = require('fs');
const readline = require('readline');

const logFile = 'C:\\Users\\Balamurugan\\.gemini\\antigravity-ide\\brain\\14342646-882e-4d6c-83a2-5752e47c2cbe\\.system_generated\\logs\\transcript.jsonl';

async function run() {
  const fileStream = fs.createReadStream(logFile);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    try {
      const step = JSON.parse(line);
      if (step.content && step.content.includes('Showing lines 1 to 800') && step.content.includes('HomeLandingPage')) {
        console.log('--- FOUND FULL VIEW_FILE OUTPUT ---');
        console.log('Step Index:', step.step_index);
        console.log('Type:', step.type);
        fs.writeFileSync('scratch/recovered_page_view_full.txt', step.content);
        console.log('Saved to scratch/recovered_page_view_full.txt');
      }
    } catch (e) {
      // ignore
    }
  }
}

run();
"
